// Click a manual screenshot to see it at full size; click again or press Esc to close.
// The screenshots are generated by scripts/manual-shots/ and live in /manual-shots/.

export function enableShotZoom() {
  let overlay: HTMLDivElement | null = null

  const close = () => {
    overlay?.remove()
    overlay = null
  }

  document.addEventListener('click', (event) => {
    const img = (event.target as HTMLElement | null)?.closest?.('.vp-doc img')
    if (!(img instanceof HTMLImageElement) || !img.src.includes('/manual-shots/')) return
    event.preventDefault()
    overlay = document.createElement('div')
    overlay.className = 'shot-zoom'
    overlay.setAttribute('role', 'dialog')
    overlay.setAttribute('aria-label', img.alt)
    const big = document.createElement('img')
    big.src = img.src
    big.alt = img.alt
    overlay.appendChild(big)
    overlay.addEventListener('click', close)
    document.body.appendChild(overlay)
  })

  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') close()
  })
}
